/**
 * OpenClaw Claude Code Skill Demo
 * Demonstrates MCP initialization, tool verification, and state persistence
 */

import * as fs from 'fs';
import * as path from 'path';

// Configuration
const CONFIG_PATH = path.join(__dirname, 'mcp_config.json');
const OUTPUT_PATH = path.join(__dirname, 'output', 'mcp_summary.json');
const PERSIST_STORE_PATH = path.join(__dirname, 'output', 'persist_store.json');

// Mock implementation simulating the openclaw-claude-code-skill API
interface MCPConfig {
  mcpServers: {
    [key: string]: {
      command: string;
      args: string[];
      status?: string;
      env?: Record<string, string>;
    };
  };
}

interface PersistStore {
  count: number;
  items: string[];
  _hasHydrated: boolean;
}

// Global state for demo
let mcpServers: Map<string, any> = new Map();
let tools: Map<string, string[]> = new Map();

// Simulated MCP functions
async function setConfigPath(configPath: string): Promise<void> {
  console.log(`[SETUP] Config path set to: ${configPath}`);
}

async function initializeMcpSystem(): Promise<void> {
  console.log('[INIT] Initializing MCP system...');

  try {
    const configData = fs.readFileSync(CONFIG_PATH, 'utf-8');
    const config: MCPConfig = JSON.parse(configData);

    for (const [serverId, serverConfig] of Object.entries(config.mcpServers)) {
      console.log(`[INIT] Starting server: ${serverId}`);
      mcpServers.set(serverId, {
        ...serverConfig,
        status: 'active',
        startedAt: new Date().toISOString()
      });

      // Simulate tools available from this server
      if (serverId === 'filesystem') {
        tools.set(serverId, [
          'read_file',
          'write_file', 
          'list_directory',
          'create_directory',
          'delete_file',
          'move_file'
        ]);
      }
    }
    console.log('[INIT] MCP system initialized successfully');
  } catch (error) {
    console.error('[INIT] Error initializing MCP:', error);
    throw error;
  }
}

async function getAllTools(): Promise<Record<string, string[]>> {
  const result: Record<string, string[]> = {};
  for (const [serverId, serverTools] of tools) {
    result[serverId] = serverTools;
  }
  return result;
}

async function getClientsStatus(): Promise<Record<string, string>> {
  const status: Record<string, string> = {};
  for (const [serverId, serverConfig] of mcpServers) {
    status[serverId] = serverConfig.status;
  }
  return status;
}

// State persistence functions
async function createPersistStore<T>(initialState: T): Promise<{ set: (state: Partial<T>) => void; get: () => T; getState: () => T }> {
  let state: T = { ...initialState } as T;
  let hasHydrated = false;

  // Try to load persisted state
  try {
    if (fs.existsSync(PERSIST_STORE_PATH)) {
      const data = fs.readFileSync(PERSIST_STORE_PATH, 'utf-8');
      const persisted = JSON.parse(data);
      state = { ...initialState, ...persisted } as T;
      hasHydrated = true;
      console.log('[STORE] State hydrated from persistent store');
    }
  } catch (error) {
    console.log('[STORE] Starting with initial state');
  }

  const store = {
    set: (newState: Partial<T>) => {
      state = { ...state, ...newState } as T;
      // Persist immediately
      fs.writeFileSync(PERSIST_STORE_PATH, JSON.stringify(state, null, 2));
      console.log(`[STORE] State updated: ${JSON.stringify(state)}`);
    },
    get: () => state,
    getState: () => ({ ...state, _hasHydrated: hasHydrated })
  };

  return store;
}

// Main demo function
async function runDemo(): Promise<void> {
  console.log('\n=== OpenClaw MCP Demo ===\n');

  // Step 1: Set config path
  await setConfigPath(CONFIG_PATH);

  // Step 2: Check tools BEFORE initialization
  console.log('\n--- Tools BEFORE initialization ---');
  const toolsBefore = await getAllTools();
  console.log('Available tools:', JSON.stringify(toolsBefore, null, 2));
  const toolCountBefore = Object.values(toolsBefore).flat().length;
  console.log(`Total tools: ${toolCountBefore}`);

  // Step 3: Initialize MCP system
  await initializeMcpSystem();

  // Step 4: Check tools AFTER initialization
  console.log('\n--- Tools AFTER initialization ---');
  const toolsAfter = await getAllTools();
  console.log('Available tools:', JSON.stringify(toolsAfter, null, 2));
  const toolCountAfter = Object.values(toolsAfter).flat().length;
  console.log(`Total tools: ${toolCountAfter}`);

  // Step 5: Get server status
  const serverStatus = await getClientsStatus();
  const activeServers = Object.keys(serverStatus).filter(id => serverStatus[id] === 'active');
  console.log('\n--- Active Servers ---');
  console.log('Active server IDs:', activeServers);

  // Step 6: State persistence demo
  console.log('\n--- State Persistence Demo ---');
  const store = await createPersistStore<{ count: number; items: string[] }>(
    { count: 0, items: [] }
  );

  // Write counter value (increment to 1)
  const currentCount = store.get().count;
  store.set({ count: currentCount + 1 });

  // Write one item to persistent store
  store.set({ items: [...store.get().items, 'demo-item-001'] });

  const finalState = store.getState();
  console.log(`Final state: ${JSON.stringify(finalState)}`);
  console.log(`Hydrated: ${finalState._hasHydrated}`);

  // Step 7: Write summary output
  const summary = {
    task_id: 'mcp-demo-001',
    timestamp: new Date().toISOString(),
    active_server_ids: activeServers,
    tool_count: toolCountAfter,
    tools_by_server: toolsAfter,
    server_status: serverStatus,
    persistence_demo: {
      counter_value: finalState.count,
      items_written: finalState.items,
      hydrated: finalState._hasHydrated
    }
  };

  // Ensure output directory exists
  const outputDir = path.dirname(OUTPUT_PATH);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(summary, null, 2));
  console.log(`\n[OUTPUT] Summary written to: ${OUTPUT_PATH}`);
  console.log('\n=== Demo Complete ===\n');
}

// Run the demo
runDemo().catch(console.error);
